#include <bits/stdc++.h>
#define MOD 1000000007LL

using namespace std;

struct Vector {
  long long values[30];
};

struct Matrix {
  long long matrix[30][30];
};

long long total, base;

int computeVal(long long num) {
  if (num < base) return num;
  return (num + computeVal(num / base)) % base;
}

Matrix matrices[30], inverse_matrices[30];
Matrix E[200][40], EI[200][40];
Vector current;

Matrix multiply(Matrix m1, Matrix m2) {
  Matrix result;
  for (int i = 0; i < base; i++) {
    for (int j = 0; j < base; j++) {
      result.matrix[i][j] = 0;
      for (int l = 0; l < base; l++) {
        result.matrix[i][j] += (m1.matrix[i][l] * m2.matrix[l][j]) % MOD;
      }
      result.matrix[i][j] %= MOD;
    }
  }
  return result;
}

Vector multiply(Matrix m, Vector v) {
  Vector v2;
  for (int i = 0; i < base; i++) {
    v2.values[i] = 0;
    for (int j = 0; j < base; j++) {
      v2.values[i] += (v.values[j] * m.matrix[i][j]) % MOD;
    }
    v2.values[i] %= MOD;
  }
  return v2;
}

void precompute() {
  for (int i = 0; i < base; i++) {
    E[0][i] = matrices[i];
    EI[0][i] = inverse_matrices[i];
  }
  int LOG = 0;
  long long t = total;
  while (t > 0) {
    LOG++;
    t /= base;
  }
  for (int j = 1; j <= LOG; j++) {
    E[j][0] = E[j - 1][0];
    EI[j][0] = EI[j - 1][0];
    for (int l = 1; l < base; l++) {
      E[j][0] = multiply(E[j - 1][l], E[j][0]);
      EI[j][0] = multiply(EI[j][0], EI[j - 1][l]);
    }
    for (int i = 1; i < base; i++) {
      E[j][i] = multiply(E[j - 1][i - 1], multiply(E[j][i - 1], EI[j - 1][i - 1]));
      EI[j][i] = multiply(E[j - 1][i - 1], multiply(EI[j][i - 1], EI[j - 1][i - 1]));
    }
  }
}

Vector solve(long long n, Vector v, int at) {
  if (n == 0) return v;
  int w = computeVal(n / base);
  v = solve(n / base, v, at + 1);
  for (int i = 0; i < n % base; i++) {
    v = multiply(E[at][(w + i) % base], v);
  }
  return v;
}

int main() {
  scanf("%lld %lld", &total, &base);
  for (int i = 0; i < base; i++) {
    current.values[i] = 1;
    for (int j = 0; j < base; j++) {
      for (int l = 0; l < base; l++) {
        if (j == l) {
          matrices[i].matrix[j][l] = 1;
          inverse_matrices[i].matrix[j][l] = 1;
        } else if (j == i) {
          matrices[i].matrix[j][l] = 1;
          inverse_matrices[i].matrix[j][l] = -1;
        } else {
          matrices[i].matrix[j][l] = 0;
          inverse_matrices[i].matrix[j][l] = 0;
        }
      }
    }
  }
  precompute();
  current = solve(total, current, 0);
  long long sum = 0;
  for (int i = 0; i < base; i++) {
    sum += current.values[i];
  }
  sum--;
  sum %= MOD;
  if (sum < 0) sum += MOD;
  while (sum % (base - 1) != 0) {
    sum += MOD;
  }
  printf("%lld\n", sum / (base - 1));
}
